function applyTheme(){document.documentElement.setAttribute('data-theme',state.theme==='light'?'light':'dark');}
function renderHome(){
 const t=DICT[state.lang]; document.getElementById('homeApp').innerHTML=homeHTML(t);
 document.querySelectorAll('#homeApp [data-scroll]').forEach(a=>a.onclick=()=>{const el=document.getElementById(a.dataset.scroll);el&&el.scrollIntoView({behavior:'smooth',block:'start'});});
 document.querySelectorAll('#homeApp [data-go="top"]').forEach(a=>a.onclick=()=>window.scrollTo({top:0,behavior:'smooth'}));
 document.querySelectorAll('#homeApp [data-atelier]').forEach(a=>a.onclick=openCatalog);
 document.querySelectorAll('#homeApp [data-atlas]').forEach(a=>a.onclick=openAtlas);
 const lb=document.querySelector('#homeApp [data-lang]'); if(lb) lb.onclick=()=>{state.lang=state.lang==='fr'?'en':'fr';renderHome();};
 const tb=document.querySelector('#homeApp [data-theme-btn]'); if(tb) tb.onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme();renderHome();};
 document.querySelectorAll('#homeApp [data-layer]').forEach(btn=>btn.onclick=()=>{state.layer=+btn.dataset.layer;const cb=document.getElementById('cutbeam');if(cb)cb.setAttribute('active-layer',state.layer);document.querySelectorAll('#homeApp [data-layer]').forEach(b=>{const on=+b.dataset.layer===state.layer;b.querySelector('.lbar').style.opacity=on?1:0;b.querySelector('.ltitle').style.opacity=on?1:.55;});});
}

/* ================= helpers ================= */
const $=id=>document.getElementById(id);
const fmt=(x,d=2)=>(isFinite(x)?x:0).toLocaleString('fr-FR',{minimumFractionDigits:d,maximumFractionDigits:d});
const cssVar=n=>getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const MATERIALS={steel:{name:"Acier",E:210,fadm:235,cvar:"--steel"},concrete:{name:"Béton",E:30,fadm:15,cvar:"--concrete"},wood:{name:"Bois",E:11,fadm:24,cvar:"--wood"}};
/* Lot 0 — perf & mémoire : throttle rAF + libération GPU réelle */
function rafThrottle(fn){let q=false;return function(){if(q)return;q=true;requestAnimationFrame(()=>{q=false;fn();});};}
function disposeObject3D(root){if(!root)return;root.traverse(n=>{if(n.geometry)n.geometry.dispose();if(n.material){const ms=Array.isArray(n.material)?n.material:[n.material];ms.forEach(m=>{for(const k in m){const v=m[k];if(v&&v.isTexture)v.dispose();}m.dispose();});}});}

/* ================= view switch ================= */
function enterLab(){$("homeApp").classList.add("hidden");$("labwrap").classList.remove("hidden");window.scrollTo(0,0);syncLabTools();}
function goHome(){teardownViz();$("labwrap").classList.add("hidden");$("homeApp").classList.remove("hidden");window.scrollTo(0,0);}
let etudeFrom='catalog';
function openCatalog(){enterLab();teardownViz();teardownAtlas();["atlas","compose","result","etude"].forEach(s=>{const el=$(s);if(el)el.classList.add("hidden");});$("catalog").classList.remove("hidden");buildCatalog();$("labDom").textContent="Ateliers";window.scrollTo(0,0);}
function buildCatalog(){
  $("catGrid").innerHTML=Object.values(AT).map(a=>`<button class="catcard" data-el="${a.id}">
    <div class="top"><span class="code">${a.code}</span><span class="fam">${a.family}</span></div>
    <h3>${a.name}</h3>
    <div class="man"><span><b>Manipule</b>${a.manip}</span><span><b>Tu lis</b>${a.read}</span></div></button>`).join("");
  $("catGrid").querySelectorAll('[data-el]').forEach(c=>c.onclick=()=>etudeOpen(c.dataset.el,'catalog'));
}
function syncLabTools(){const lb=$("data-lang2")||document.querySelector('[data-lang2]'),tb=document.querySelector('[data-theme2]');if(lb)lb.textContent=state.lang==='fr'?'EN':'FR';if(tb)tb.textContent=state.theme==='dark'?(state.lang==='fr'?'Clair':'Light'):(state.lang==='fr'?'Sombre':'Dark');}
document.querySelectorAll('[data-home]').forEach(b=>b.onclick=goHome);
document.querySelectorAll('[data-catalog]').forEach(b=>b.onclick=openCatalog);
document.querySelectorAll('[data-atlas]').forEach(b=>b.onclick=openAtlas);
$("etudeBack").onclick=()=>{etudeFrom==='atlas'?openAtlas():openCatalog();};
document.querySelector('[data-lang2]').onclick=()=>{state.lang=state.lang==='fr'?'en':'fr';renderHome();syncLabTools();};
document.querySelector('[data-theme2]').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme();renderHome();syncLabTools();if(_viz&&_viz.recolor)_viz.recolor();};

/* ================= chassis engine ================= */
function plan(steps,tasks,sel){const chosen=new Set(),st=[...sel];const depth=(id,seen)=>{seen=seen||new Set();const s=tasks[id];if(!s||seen.has(id))return 0;const rq=(s.requires||[]).filter(r=>tasks[r]);return rq.length?1+Math.max(...rq.map(r=>depth(r,new Set([...seen,id])))):0;};
  while(st.length){const id=st.pop();if(chosen.has(id)||!tasks[id])continue;chosen.add(id);(tasks[id].requires||[]).forEach(r=>st.push(r));}
  return [...chosen].sort((a,b)=>(steps.indexOf(tasks[a].step)-steps.indexOf(tasks[b].step))||(depth(a)-depth(b))||(a<b?-1:1));}
function runPipeline(at,sel,inputs){const ctx={data:{...inputs},results:{},summary:{},tables:{},stepsUsed:new Set()};
  for(const id of plan(at.stepIds,at.tasks,sel)){const sp=at.tasks[id];const r=sp.run(ctx)||{};Object.assign(ctx.summary,r.summary||{});for(const[t,rows]of Object.entries(r.tables||{}))ctx.tables[t]=rows;ctx.results[id]=r.display||{};ctx.stepsUsed.add(sp.step);}return ctx;}

