/* solveBeam / interp / solveTruss vivent dans js/solvers.js (purs, testés),
   chargé avant main.js. Ils restent disponibles en global. */

/* ================= 8 ATELIERS — all 3D, all manipulable ================= */
/* Shared interaction: a load handle the student DRAGS along the structure +
   an intensity slider; the physics recomputes live. No 2D, no static scenes. */
function barMesh(a,b,r,mat){const va=new THREE.Vector3(...a),vb=new THREE.Vector3(...b),d=new THREE.Vector3().subVectors(vb,va);const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,d.length(),12),mat);m.position.copy(va).addScaledVector(d,.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());return m;}
function dragCtl(o,handles,onMove,onHit){const cv=$("view"),ray=new THREE.Raycaster(),ndc=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,0,1),0),hit=new THREE.Vector3();let dg=false;const hs=()=>Array.isArray(handles)?handles:[handles];
  const sn=e=>{const r=cv.getBoundingClientRect();ndc.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height*2-1));};
  cv.addEventListener('pointerdown',e=>{sn(e);ray.setFromCamera(ndc,o.camera);const i=ray.intersectObjects(hs(),true);if(i.length){dg=true;o.controls.enabled=false;try{cv.setPointerCapture(e.pointerId);}catch(_){}onHit&&onHit(i[0]);}});
  const doMove=()=>{ray.setFromCamera(ndc,o.camera);if(ray.ray.intersectPlane(plane,hit))onMove(hit);};
  const throttledMove=rafThrottle(doMove);
  cv.addEventListener('pointermove',e=>{sn(e);if(dg){throttledMove();}else{ray.setFromCamera(ndc,o.camera);cv.style.cursor=ray.intersectObjects(hs(),true).length?'grab':'default';}});
  const end=()=>{dg=false;o.controls.enabled=true;cv.style.cursor='default';};cv.addEventListener('pointerup',end);cv.addEventListener('pointercancel',end);}
function toolbar(html){$("vtoolbar").innerHTML=html;}
function slider(id,label,min,max,step,val,unit){return `<div class="grp">${label} <input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${val}"><span id="${id}L" class="mono">${val} ${unit||''}</span></div>`;}
function loadArrow(col,tall,rad){const m=new THREE.MeshStandardMaterial({color:new THREE.Color(col),emissive:new THREE.Color(col),emissiveIntensity:.2,roughness:.5});const g=new THREE.Group();const sh=new THREE.Mesh(new THREE.CylinderGeometry(rad,rad,tall,12),m);sh.position.y=tall/2+rad*3;const hd=new THREE.Mesh(new THREE.ConeGeometry(rad*3,rad*7,14),m);hd.position.y=rad*3.2;hd.rotation.x=Math.PI;const grab=new THREE.Mesh(new THREE.SphereGeometry(rad*7,16,16),new THREE.MeshBasicMaterial({visible:false}));g.add(sh,hd,grab);g.userData.grab=grab;return g;}
const AT={};

/* ---------- 1. POUTRE ---------- */
AT.poutre={id:'poutre',code:'RDM',family:'Poutres',name:'Poutre sur deux appuis',sub:'Glisse la charge le long de la travée, règle son intensité, change le matériau. Tout recalcule en direct.',
 manip:'glisse la charge, règle P, change le matériau',read:'déformée, M(x), contraintes',ready:true,
 stepIds:['modele','section','charge','resolution','deformee','contraintes'],
 stepLabels:{modele:'Modèle',section:'Section & matériau',charge:'Chargement',resolution:'Résolution',deformee:'Déformée',contraintes:'Contraintes'},
 params:[
  {id:'L',label:'Portée L',short:'L',type:'range',min:2,max:10,step:.5,unit:'m',dec:1},
  {id:'mat',label:'Matériau',type:'select',options:[{v:'steel',l:'Acier'},{v:'concrete',l:'Béton'},{v:'wood',l:'Bois'}]},
  {id:'b',label:'Largeur b',short:'b',type:'number',min:50,max:600,step:10},
  {id:'h',label:'Hauteur h',short:'h',type:'number',min:80,max:900,step:10},
  {id:'a',label:'Position charge a',short:'a',type:'range',min:0,max:10,step:.25,unit:'m',dec:1},
  {id:'P',label:'Charge P',short:'P',type:'range',min:10,max:400,step:10,unit:'kN',dec:0},
 ],
 cases:[
  {label:'Charge centrée',dd:'Ponctuelle au milieu.',meta:'L=6 · P=150 · acier',set:{L:6,mat:'steel',b:200,h:400,a:3,P:150}},
  {label:'Charge excentrée',dd:'Au tiers de la portée.',meta:'L=6 · P=120 @2m',set:{L:6,mat:'steel',b:200,h:400,a:2,P:120}},
  {label:'Poutre bois longue',dd:'Portée 8 m, flèche critique.',meta:'L=8 · P=40 · bois',set:{L:8,mat:'wood',b:200,h:400,a:4,P:40}},
 ],
 questions:[
  {id:'defl',label:'Observer la déformée',resume:'Comment la poutre plie.',tasks:['define_model','set_section','apply_loads','reactions','internal_forces','deflection']},
  {id:'stress',label:'Voir les contraintes',resume:'Compression / traction.',tasks:['define_model','set_section','apply_loads','reactions','internal_forces','deflection','bending_stress']},
  {id:'full',label:'TP complet',resume:'Tout.',tasks:['define_model','set_section','apply_loads','reactions','internal_forces','deflection','bending_stress']},
 ],
 tasks:{
  define_model:{label:'Définir la poutre',step:'modele',run:c=>({summary:{L:c.data.L}})},
  set_section:{label:'Section & matériau',step:'section',run:c=>{c.data.I=c.data.b*Math.pow(c.data.h,3)/12;return{summary:{I:c.data.I}};}},
  apply_loads:{label:'Appliquer la charge',step:'charge',run:c=>({})},
  reactions:{label:'Réactions',step:'resolution',requires:['define_model','set_section','apply_loads'],run:c=>{const s=solveBeam(c.data.L,c.data.E*c.data.I,c.data.point,null);c.data.sol=s;return{summary:{RA:s.RA,RB:s.RB}};}},
  internal_forces:{label:'V & M',step:'resolution',requires:['reactions'],run:c=>({summary:{Mmax:c.data.sol.Mmax.v}})},
  deflection:{label:'Flèche',step:'deformee',requires:['internal_forces'],run:c=>({summary:{ymax:c.data.sol.ymax.v}})},
  bending_stress:{label:'Contrainte σ',step:'contraintes',requires:['internal_forces','set_section'],run:c=>({summary:{sigma:Math.abs(c.data.sol.Mmax.v)*(c.data.h/2)/c.data.I/1e6}})},
 },
 prepare(P){const bm=P.b/1000,hm=P.h/1000;return{L:P.L,b:bm,h:hm,I:bm*Math.pow(hm,3)/12,E:MATERIALS[P.mat].E*1e9,mat:P.mat,point:{a:Math.min(P.a,P.L),P:P.P*1e3}};},
 result(ctx,inputs){
  const o=make3D();_viz=o;o.pick=[];
  const geomLen=10,hW=Math.max(.5,geomLen*(inputs.h/inputs.L)),wW=Math.max(.3,geomLen*(inputs.b/inputs.L));
  const st={a:inputs.point.a,P:inputs.point.P,mat:inputs.mat};
  const X=x=>-geomLen/2+geomLen*(x/inputs.L);
  const supMat=new THREE.MeshStandardMaterial({color:new THREE.Color(cssVar('--faint')),roughness:.6});
  const pin=new THREE.Mesh(new THREE.ConeGeometry(hW*.5,hW*.9,4),supMat.clone());pin.rotation.y=Math.PI/4;pin.position.set(X(0),-hW/2-hW*.45,0);o.scene.add(pin);
  const roll=new THREE.Mesh(new THREE.CylinderGeometry(hW*.42,hW*.42,wW*1.1,18),supMat.clone());roll.rotation.x=Math.PI/2;roll.position.set(X(inputs.L),-hW/2-hW*.42,0);o.scene.add(roll);
  const handle=loadArrow(cssVar('--tension'),hW*1.3,hW*.09);o.scene.add(handle);
  let sol,ampW;
  function solve(){sol=solveBeam(inputs.L,MATERIALS[st.mat].E*1e9*inputs.I,{a:st.a,P:st.P},null);const sw=solveBeam(inputs.L,MATERIALS.wood.E*1e9*inputs.I,{a:st.a,P:st.P},null);ampW=(1.15*hW)/Math.max(1e-9,Math.abs(sw.ymax.v));o.sol=sol;o.ampW=ampW;}
  function rebuild(){solve();const Mmax=Math.max(1e-9,Math.abs(sol.Mmax.v));
    if(o.beam){o.scene.remove(o.beam);o.beam.geometry.dispose();}
    const geo=new THREE.BoxGeometry(geomLen,hW,wW,140,4,2),pos=geo.attributes.position,col=[];
    const base=new THREE.Color(cssVar('--neutral')),cC=new THREE.Color(cssVar('--compress')),cT=new THREE.Color(cssVar('--tension'));
    for(let i=0;i<pos.count;i++){const lx=pos.getX(i),ly=pos.getY(i),rx=(lx+geomLen/2)/geomLen*inputs.L,d=interp(sol.y,inputs.L,rx);pos.setY(i,ly+d*ampW);
      const M=interp(sol.M,inputs.L,rx),rY=(ly/hW)*inputs.h,comp=(M>=0)===(ly>=0),t=Math.min(1,Math.abs(M)*Math.abs(rY)/(Mmax*(inputs.h/2)+1e-9));const c=base.clone().lerp(comp?cC:cT,t*.92);col.push(c.r,c.g,c.b);}
    geo.setAttribute('color',new THREE.Float32BufferAttribute(col,3));geo.computeVertexNormals();
    o.beam=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.55}));o.scene.add(o.beam);
    const hy=interp(sol.y,inputs.L,st.a)*ampW+hW/2;handle.position.set(X(st.a),hy,0);
    side();}
  o.recolor=rebuild;
  o.camera.position.set(geomLen*.5,geomLen*.42,geomLen*.9);o.controls.target.set(0,-hW*.2,0);o.controls.update();o.loop();
  toolbar(`<div class="matsw" id="matSw"></div>`+slider('pSl','Charge P',10,400,10,st.P/1e3,'kN'));
  $("matSw").innerHTML=Object.keys(MATERIALS).map(m=>`<button data-m="${m}" class="${m===st.mat?'active':''}">${MATERIALS[m].name}</button>`).join('');
  $("matSw").querySelectorAll('button').forEach(btn=>btn.onclick=()=>{st.mat=btn.dataset.m;$("matSw").querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===btn));rebuild();});
  $("pSl").oninput=e=>{st.P=(+e.target.value)*1e3;$("pSlL").textContent=e.target.value+' kN';rebuild();};
  $("vhint").textContent='Glisse la flèche le long de la poutre · règle P · tourne la scène';
  $("view").insertAdjacentHTML('afterend','<div class="cmaplegend"><span><i style="background:var(--compress)"></i>compression</span><span><i style="background:var(--tension)"></i>traction</span></div>');
  dragCtl(o,handle.userData.grab,hit=>{let x=(hit.x+geomLen/2)/geomLen*inputs.L;st.a=Math.max(0,Math.min(inputs.L,x));rebuild();});
  function side(){const sig=Math.abs(sol.Mmax.v)*(inputs.h/2)/inputs.I/1e6;
    let html=ro([['R_A',fmt(sol.RA/1e3,1),'kN'],['R_B',fmt(sol.RB/1e3,1),'kN'],['M max',fmt(Math.abs(sol.Mmax.v)/1e3,1),'kN·m'],['Flèche',fmt(Math.abs(sol.ymax.v)*1000,1),'mm']].concat('sigma'in ctx.summary?[['σ max',fmt(sig,0),'MPa'],['charge a',fmt(st.a,2),'m']]:[['charge a',fmt(st.a,2),'m']]));
    html+=`<div><h4>Pas à pas</h4>${stepx('Réactions','ΣF=0 · ΣM=0','R_A '+fmt(sol.RA/1e3,1)+' · R_B '+fmt(sol.RB/1e3,1)+' kN')}${stepx('Flèche','EI·y″=M(x)','y max '+fmt(Math.abs(sol.ymax.v)*1000,1)+' mm')}</div>`;
    $("side").innerHTML=html;
    const fadm=MATERIALS[st.mat].fadm,over=sig>fadm;
    if(_viz)_viz.dim={rows:[['σ max',fmt(sig,0),'MPa'],['σ adm',fmt(fadm,0),'MPa'],['Matériau',MATERIALS[st.mat].name,'']],
      verdict:over?{state:'bad',tag:'Dépassé',text:'σ max > σ adm — augmente la section ou change de matériau'}:{state:'ok',tag:'Vérifié',text:'σ max ≤ σ adm — section vérifiée en flexion'},
      note:'Dimensionnement élastique : σ = M·(h/2)/I comparée à la contrainte admissible du matériau.'};
    syncPhases();}
  rebuild();
 }
};

/* ---------- 2. TREILLIS ---------- */
AT.treillis={id:'treillis',code:'RDM',family:'Poutres',name:'Treillis plan',sub:'Glisse la charge le long de la membrure basse : les barres se recolorent en direct, traction ou compression.',
 manip:'glisse la charge sur les nœuds, règle P',read:'effort dans chaque barre',ready:true,
 stepIds:['geometrie','chargement','equilibre','efforts'],
 stepLabels:{geometrie:'Géométrie',chargement:'Chargement',equilibre:'Équilibre',efforts:'Efforts'},
 params:[{id:'H',label:'Hauteur H',short:'H',type:'range',min:1,max:4,step:.5,unit:'m',dec:1},{id:'P',label:'Charge P',short:'P',type:'range',min:20,max:300,step:10,unit:'kN',dec:0}],
 cases:[{label:'Ferme standard',dd:'8 m, H=2 m.',meta:'H=2 · P=100',set:{H:2,P:100}},{label:'Ferme haute',dd:'Barres moins chargées.',meta:'H=3.5',set:{H:3.5,P:150}}],
 questions:[{id:'forces',label:'Efforts dans les barres',resume:'Traction / compression.',tasks:['define_geom','apply_load','reactions_t','member_forces']},{id:'full',label:'TP complet',resume:'Tout.',tasks:['define_geom','apply_load','reactions_t','member_forces']}],
 tasks:{define_geom:{label:'Poser la ferme',step:'geometrie',run:c=>({})},apply_load:{label:'Appliquer la charge',step:'chargement',run:c=>({})},reactions_t:{label:'Réactions',step:'equilibre',requires:['define_geom','apply_load'],run:c=>({})},member_forces:{label:'Effort par barre',step:'efforts',requires:['reactions_t'],run:c=>({})}},
 prepare(P){return{H:P.H,P:P.P*1e3};},
 result(ctx,inputs){
  const o=make3D();_viz=o;const H=inputs.H,span=8;
  const bx=[0,2,4,6,8],tx=[1,3,5,7];const nodes=[];bx.forEach((x,i)=>nodes.push({x,y:0,support:i===0?'pin':(i===4?'roller':null)}));tx.forEach(x=>nodes.push({x,y:H}));
  const members=[[0,1],[1,2],[2,3],[3,4],[5,6],[6,7],[7,8],[0,5],[5,1],[1,6],[6,2],[2,7],[7,3],[3,8],[8,4]];
  const loadableBottom=[1,2,3];const st={ni:2,P:inputs.P};
  const X=x=>x-4;const nodeMat=new THREE.MeshStandardMaterial({color:new THREE.Color(cssVar('--faint')),roughness:.5,metalness:.3});
  nodes.forEach(n=>{const s=new THREE.Mesh(new THREE.SphereGeometry(.13,14,14),nodeMat);s.position.set(X(n.x),n.y,0);o.scene.add(s);if(n.support){const sup=new THREE.Mesh(new THREE.ConeGeometry(.3,.45,4),nodeMat.clone());sup.position.set(X(n.x),-.32,0);sup.rotation.y=Math.PI/4;o.scene.add(sup);}});
  o.bars=members.map(()=>null);
  const handle=loadArrow(cssVar('--tension'),1.1,.05);o.scene.add(handle);
  let sol,Nmax;
  function rebuild(){const loads={};loads[st.ni]=[0,-st.P];sol=solveTruss(nodes,members,loads);const f=sol.forces;Nmax=Math.max(1e-9,...f.map(Math.abs));
    members.forEach((mm,k)=>{if(o.bars[k]){o.scene.remove(o.bars[k]);o.bars[k].geometry.dispose();}const a=nodes[mm[0]],b=nodes[mm[1]],fv=f[k]||0;const t=Math.min(1,Math.abs(fv)/Nmax);
      const cc=new THREE.Color(cssVar('--neutral')).lerp(new THREE.Color(fv>=0?cssVar('--tension'):cssVar('--compress')),.28+.72*t);
      const bar=barMesh([X(a.x),a.y,0],[X(b.x),b.y,0],.06+.05*t,new THREE.MeshStandardMaterial({color:cc,emissive:cc,emissiveIntensity:.12,roughness:.5}));bar.userData={f:fv};o.scene.add(bar);o.bars[k]=bar;});
    handle.position.set(X(nodes[st.ni].x),.55,0);side();}
  o.recolor=rebuild;
  o.camera.position.set(1,3.2,12);o.controls.target.set(0,H/2,0);o.controls.update();o.loop();
  toolbar(slider('pSl','Charge P',20,300,10,st.P/1e3,'kN'));
  $("pSl").oninput=e=>{st.P=(+e.target.value)*1e3;$("pSlL").textContent=e.target.value+' kN';rebuild();};
  $("vhint").textContent='Glisse la charge d’un nœud à l’autre · règle P · tourne';
  $("view").insertAdjacentHTML('afterend','<div class="cmaplegend"><span><i style="background:var(--tension)"></i>traction</span><span><i style="background:var(--compress)"></i>compression</span></div>');
  dragCtl(o,handle.userData.grab,hit=>{const wx=hit.x+4;let best=loadableBottom[0],bd=1e9;loadableBottom.forEach(i=>{const d=Math.abs(nodes[i].x-wx);if(d<bd){bd=d;best=i;}});if(best!==st.ni){st.ni=best;rebuild();}else{handle.position.set(X(nodes[st.ni].x),.55,0);}});
  function side(){const RA=Math.abs(sol.reactions[1]||0),RB=Math.abs(sol.reactions[sol.reactions.length-1]||0);
    let html=ro([['R_A',fmt(RA/1e3,1),'kN'],['R_B',fmt(RB/1e3,1),'kN'],['N max',fmt(Nmax/1e3,1),'kN'],['Nœud chargé',st.ni,'']]);
    html+=`<div class="idcard" id="idCard">Tape une barre pour lire son effort. Glisse la charge pour voir tout changer.</div>`;
    html+=`<div><h4>Pas à pas</h4>${stepx('Équilibre global','ΣF=0 · ΣM=0','réactions aux appuis')}${stepx('Méthode des nœuds','ΣF=0 à chaque nœud','effort de chaque barre')}</div>`;
    $("side").innerHTML=html;
    const ff=sol.forces||[],maxT=Math.max(0,...ff),maxC=Math.min(0,...ff);
    if(_viz)_viz.dim={rows:[['N max traction',fmt(maxT/1e3,1),'kN'],['N max compression',fmt(Math.abs(maxC)/1e3,1),'kN'],['Barres',ff.length,'']],
      verdict:{state:'info',tag:'Efforts',text:'Traction → section d’acier/bois suffisante ; compression → vérifier le flambement (barres à surdimensionner)'},
      note:'Efforts issus de la statique (méthode des nœuds) → base du dimensionnement bois/métal de chaque barre.'};
    syncPhases();}
  rebuild();
  // tap a bar to read
  const ray=new THREE.Raycaster(),ndc=new THREE.Vector2();let dn=null;const cv=$("view");
  cv.addEventListener('pointerdown',e=>dn=[e.clientX,e.clientY]);
  cv.addEventListener('pointerup',e=>{if(!dn)return;const mv=Math.hypot(e.clientX-dn[0],e.clientY-dn[1]);dn=null;if(mv>6)return;const r=cv.getBoundingClientRect();ndc.set((e.clientX-r.left)/r.width*2-1,-((e.clientY-r.top)/r.height*2-1));ray.setFromCamera(ndc,o.camera);const hits=ray.intersectObjects(o.bars.filter(Boolean),false);const card=$("idCard");if(hits.length&&card){const f=hits[0].object.userData.f||0,ten=f>=0;card.innerHTML=`<span class="tag" style="background:${(ten?cssVar('--tension'):cssVar('--compress'))}22;color:${ten?cssVar('--tension'):cssVar('--compress')}">Barre</span><br><b>${ten?'Traction':'Compression'}</b><div class="val">N = ${fmt(f/1e3,1)} kN</div>`;}});
 }
};

/* ---------- 3. SECTION BA (3D beam, draggable load → moment) ---------- */
AT.section={id:'section',code:'BA',family:'Poutres',name:'Section en flexion simple',sub:'Poutre béton armé en 3D. Glisse la charge, augmente-la : compare le moment appliqué au moment résistant.',
 manip:'glisse la charge, règle P, varie les aciers',read:'moment appliqué vs résistant, pivot',ready:true,
 stepIds:['section','materiaux','charge','verif'],
 stepLabels:{section:'Section',materiaux:'Matériaux',charge:'Chargement',verif:'Vérification'},
 params:[{id:'b',label:'Largeur b',short:'b',type:'number',min:150,max:600,step:10},{id:'d',label:'Hauteur utile d',short:'d',type:'range',min:200,max:800,step:10,unit:'mm',dec:0},{id:'As',label:'Aciers As',short:'As',type:'range',min:200,max:4000,step:50,unit:'mm²',dec:0},{id:'fc',label:'Béton',type:'select',options:[{v:20,l:'C20'},{v:25,l:'C25'},{v:30,l:'C30'},{v:40,l:'C40'}]},{id:'fe',label:'Acier',type:'select',options:[{v:400,l:'fe400'},{v:500,l:'fe500'}]},{id:'L',label:'Portée',short:'L',type:'range',min:3,max:9,step:.5,unit:'m',dec:1},{id:'P',label:'Charge P',short:'P',type:'range',min:20,max:400,step:10,unit:'kN',dec:0}],
 cases:[{label:'Poutre courante',dd:'30×50, 3HA16.',meta:'b300 d450 As1000',set:{b:300,d:450,As:1000,fc:25,fe:500,L:6,P:120}},{label:'Sous-armée',dd:'Peu d’acier.',meta:'As=400',set:{b:300,d:450,As:400,fc:25,fe:500,L:6,P:120}},{label:'Surchargée',dd:'Pousse P jusqu’à la rupture.',meta:'P fort',set:{b:300,d:450,As:1000,fc:25,fe:500,L:6,P:300}}],
 questions:[{id:'cap',label:'Capacité de la section',resume:'Moment résistant, pivot.',tasks:['def_section','set_mat','apply_M','moment_res','check_cap']},{id:'full',label:'TP complet',resume:'Tout.',tasks:['def_section','set_mat','apply_M','moment_res','check_cap']}],
 tasks:{def_section:{label:'Définir la section',step:'section',run:c=>({summary:{b:c.data.b,d:c.data.d}})},set_mat:{label:'Matériaux',step:'materiaux',run:c=>({})},apply_M:{label:'Appliquer la charge',step:'charge',run:c=>({})},moment_res:{label:'Moment résistant',step:'verif',requires:['def_section'],run:c=>{const fe=c.data.fe/1.15,fcd=.85*c.data.fc/1.5;const x=c.data.As*fe/(.8*c.data.b*fcd);const MR=c.data.As*fe*(c.data.d-.4*x)/1e6;return{summary:{x,MR}};}},check_cap:{label:'Applique / résiste',step:'verif',requires:['moment_res'],run:c=>({summary:{ratio:c.data.x/c.data.d}})}},
 prepare(P){return{b:+P.b,d:+P.d,As:+P.As,fc:+P.fc,fe:+P.fe,L:+P.L,P:+P.P};},
 result(ctx,inputs){
  const o=make3D();_viz=o;const S=ctx.summary;const MR=S.MR||0;
  const geomLen=9,hW=Math.max(.7,geomLen*((inputs.d*1.15/1000)/inputs.L)),wW=Math.max(.5,geomLen*((inputs.b/1000)/inputs.L));
  const X=x=>-geomLen/2+geomLen*(x/inputs.L);const st={a:inputs.L/2,P:inputs.P*1e3};
  const supMat=new THREE.MeshStandardMaterial({color:new THREE.Color(cssVar('--faint')),roughness:.6});
  [0,inputs.L].forEach((xx,i)=>{const s=new THREE.Mesh(i?new THREE.CylinderGeometry(hW*.4,hW*.4,wW*1.1,16):new THREE.ConeGeometry(hW*.5,hW*.9,4),supMat.clone());if(i)s.rotation.x=Math.PI/2;else s.rotation.y=Math.PI/4;s.position.set(X(xx),-hW/2-hW*.45,0);o.scene.add(s);});
  const handle=loadArrow(cssVar('--tension'),hW*1.2,hW*.08);o.scene.add(handle);
  let sol,ampW,beam,steel,czone;
  function EIcr(){return 3e10*(inputs.b/1000)*Math.pow(inputs.d*1.15/1000,3)/12;}
  function rebuild(){sol=solveBeam(inputs.L,EIcr(),{a:st.a,P:st.P},null);ampW=(1.0*hW)/Math.max(1e-9,Math.abs(solveBeam(inputs.L,EIcr(),{a:inputs.L/2,P:400e3},null).ymax.v));o.sol=sol;
    const Mapp=Math.abs(sol.Mmax.v)/1e3;const over=Mapp>MR;
    if(beam){o.scene.remove(beam);beam.geometry.dispose();}
    const geo=new THREE.BoxGeometry(geomLen,hW,wW,120,3,1),pos=geo.attributes.position;for(let i=0;i<pos.count;i++){const lx=pos.getX(i),rx=(lx+geomLen/2)/geomLen*inputs.L,d=interp(sol.y,inputs.L,rx);pos.setY(i,pos.getY(i)+d*ampW);}geo.computeVertexNormals();
    const cc=new THREE.Color(over?cssVar('--bad'):cssVar('--concrete'));beam=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:cc,roughness:.85,transparent:true,opacity:.55}));o.scene.add(beam);
    if(steel){o.scene.remove(steel);steel.geometry.dispose();}const sg=new THREE.BufferGeometry();const pts=[];for(let i=0;i<=60;i++){const rx=inputs.L*i/60,d=interp(sol.y,inputs.L,rx);pts.push(new THREE.Vector3(X(rx),-hW*0.32+d*ampW,0));}sg.setFromPoints(pts);steel=new THREE.Line(sg,new THREE.LineBasicMaterial({color:new THREE.Color(cssVar('--tension')),linewidth:2}));o.scene.add(steel);
    const hy=interp(sol.y,inputs.L,st.a)*ampW+hW/2;handle.position.set(X(st.a),hy,0);side(Mapp,over);}
  o.recolor=rebuild;
  o.camera.position.set(geomLen*.5,geomLen*.4,geomLen*.9);o.controls.target.set(0,-hW*.2,0);o.controls.update();o.loop();
  toolbar(slider('pSl','Charge P',20,400,10,st.P/1e3,'kN')+slider('asSl','Aciers As',200,4000,50,inputs.As,'mm²'));
  $("pSl").oninput=e=>{st.P=(+e.target.value)*1e3;$("pSlL").textContent=e.target.value+' kN';rebuild();};
  $("asSl").oninput=e=>{inputs.As=+e.target.value;$("asSlL").textContent=e.target.value+' mm²';const fe=inputs.fe/1.15,fcd=.85*inputs.fc/1.5;S.x=inputs.As*fe/(.8*inputs.b*fcd);S.MR=inputs.As*fe*(inputs.d-.4*S.x)/1e6;rebuild();};
  $("vhint").textContent='Glisse la charge · monte P jusqu’à la rupture · varie les aciers';
  dragCtl(o,handle.userData.grab,hit=>{let x=(hit.x+geomLen/2)/geomLen*inputs.L;st.a=Math.max(0,Math.min(inputs.L,x));rebuild();});
  function side(Mapp,over){let html=ro([['M appliqué',fmt(Mapp,0),'kN·m'],['M résistant',fmt(S.MR||MR,0),'kN·m'],['Aciers',fmt(inputs.As,0),'mm²'],['Axe neutre x',fmt(S.x||0,0),'mm']]);
    html+=`<div class="idcard"><span class="tag" style="background:${(over?cssVar('--bad'):cssVar('--ok'))}22;color:${over?cssVar('--bad'):cssVar('--ok')}">${over?'Rupture':'OK'}</span><br><b>${over?'M appliqué > M résistant':'M appliqué ≤ M résistant'}</b><div class="desc">${over?'La section cède : ajoute des aciers ou réduis la charge.':'La section encaisse le moment appliqué.'}</div></div>`;
    html+=`<div><h4>Pas à pas</h4>${stepx('Moment résistant','M_R = As·fyd·(d−0.4x)','M_R = '+fmt(S.MR||MR,0)+' kN·m')}${stepx('Moment appliqué','M = f(P, position)','M = '+fmt(Mapp,0)+' kN·m')}</div>`;
    $("side").innerHTML=html;
    if(_viz)_viz.dim={rows:[['M appliqué',fmt(Mapp,0),'kN·m'],['M résistant',fmt(S.MR||MR,0),'kN·m'],['Axe neutre x',fmt(S.x||0,0),'mm']],
      verdict:over?{state:'bad',tag:'Rupture',text:'M appliqué > M résistant — ajoute des aciers ou réduis la charge'}:{state:'ok',tag:'Vérifié',text:'M appliqué ≤ M résistant — section béton armé OK'},
      note:'Dimensionnement béton armé : équilibre béton comprimé / aciers tendus (pivot A ou B).'};
    syncPhases();}
  rebuild();
 }
};

/* ---------- 4. POTEAU (flambement) ---------- */
AT.poteau={id:'poteau',code:'CM',family:'Poteaux',name:'Poteau comprimé',sub:'Tire la charge vers le bas en tête : à la charge critique d’Euler, le poteau flambe sous tes yeux.',
 manip:'tire l’effort N, change les appuis',read:'charge critique, élancement',ready:true,
 stepIds:['modele','section','charge','flambement'],
 stepLabels:{modele:'Modèle',section:'Section',charge:'Chargement',flambement:'Flambement'},
 params:[{id:'L',label:'Longueur L',short:'L',type:'range',min:2,max:8,step:.5,unit:'m',dec:1},{id:'b',label:'Côté b',short:'b',type:'number',min:60,max:400,step:10},{id:'h',label:'Côté h',short:'h',type:'number',min:60,max:400,step:10},{id:'end',label:'Appuis',type:'select',options:[{v:1,l:'Rotulé-rotulé'},{v:0.7,l:'Encastré-rotulé'},{v:0.5,l:'Encastré-encastré'},{v:2,l:'Console'}]},{id:'mat',label:'Matériau',type:'select',options:[{v:'steel',l:'Acier'},{v:'wood',l:'Bois'},{v:'concrete',l:'Béton'}]},{id:'N',label:'Effort N',short:'N',type:'range',min:50,max:5000,step:50,unit:'kN',dec:0}],
 cases:[{label:'Poteau acier',dd:'Rotulé, 4 m.',meta:'100×100 · N=800',set:{L:4,b:100,h:100,end:1,mat:'steel',N:800}},{label:'Poteau élancé',dd:'Long et fin.',meta:'L=6 · 80×80',set:{L:6,b:80,h:80,end:1,mat:'steel',N:400}},{label:'Console',dd:'Encastré-libre.',meta:'k=2',set:{L:3,b:120,h:120,end:2,mat:'steel',N:600}}],
 questions:[{id:'ncr',label:'Charge critique',resume:'Quand ça flambe.',tasks:['def_col','set_sec','set_load','buckle']},{id:'full',label:'TP complet',resume:'Tout.',tasks:['def_col','set_sec','set_load','buckle']}],
 tasks:{def_col:{label:'Définir le poteau',step:'modele',run:c=>({summary:{L:c.data.L}})},set_sec:{label:'Section',step:'section',run:c=>{c.data.I=c.data.b*Math.pow(c.data.h,3)/12;c.data.A=c.data.b*c.data.h;return{summary:{}};}},set_load:{label:'Effort',step:'charge',run:c=>({})},buckle:{label:'Charge critique',step:'flambement',requires:['def_col','set_sec','set_load'],run:c=>{const Lf=c.data.end*c.data.L,Ncr=Math.PI**2*c.data.E*c.data.I/(Lf*Lf),i=Math.sqrt(c.data.I/c.data.A),lam=Lf/i;return{summary:{Ncr,lam}};}}},
 prepare(P){const bm=P.b/1000,hm=P.h/1000;return{L:P.L,b:bm,h:hm,I:bm*Math.pow(hm,3)/12,A:bm*hm,E:MATERIALS[P.mat].E*1e9,end:+P.end,N:P.N*1e3};},
 result(ctx,inputs){
  const o=make3D();_viz=o;const S=ctx.summary;const Lw=6,bw=Math.max(.25,Lw*(inputs.b/inputs.L)*.5),dw=Math.max(.25,Lw*(inputs.h/inputs.L)*.5);
  const st={N:inputs.N};let col;
  const base=new THREE.Mesh(new THREE.BoxGeometry(bw*2.4,.3,dw*2.4),new THREE.MeshStandardMaterial({color:new THREE.Color(cssVar('--faint'))}));base.position.y=-Lw/2-.15;o.scene.add(base);
  const handle=loadArrow(cssVar('--tension'),Lw*.16,bw*.4);o.scene.add(handle);
  function rebuild(){const ratio=st.N/S.Ncr,over=ratio>=1,amp=Math.min(1.5,ratio*ratio*.95);
    if(col){o.scene.remove(col);col.geometry.dispose();}
    const geo=new THREE.BoxGeometry(bw,Lw,dw,1,40,1),pos=geo.attributes.position;for(let i=0;i<pos.count;i++){const f=(pos.getY(i)+Lw/2)/Lw;pos.setX(i,pos.getX(i)+amp*Math.sin(Math.PI*f));}geo.computeVertexNormals();
    const c=new THREE.Color(over?cssVar('--bad'):cssVar('--steel'));col=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:c,roughness:.5,metalness:.3,emissive:c,emissiveIntensity:over?.25:.05}));o.scene.add(col);
    handle.position.set(amp,Lw/2+.1,0);side(ratio,over);}
  o.recolor=rebuild;
  o.camera.position.set(4,1.2,7.5);o.controls.target.set(0,0,0);o.controls.update();o.loop();
  toolbar(slider('nSl','Effort N',50,5000,50,st.N/1e3,'kN'));
  $("nSl").oninput=e=>{st.N=(+e.target.value)*1e3;$("nSlL").textContent=e.target.value+' kN';rebuild();};
  $("vhint").textContent='Tire N vers le haut du poteau · à Ncr, il flambe';
  dragCtl(o,handle.userData.grab,hit=>{// vertical drag maps to N: higher pull = more N
    const frac=Math.max(0,Math.min(1,(hit.y-(-Lw/2))/(Lw*1.4)));st.N=(50+ frac*4950)*1e3;$("nSl").value=Math.round(st.N/1e3);$("nSlL").textContent=Math.round(st.N/1e3)+' kN';rebuild();});
  function side(ratio,over){let html=ro([['N critique',fmt(S.Ncr/1e3,0),'kN'],['Élancement λ',fmt(S.lam,0),''],['N appliqué',fmt(st.N/1e3,0),'kN'],['N/Ncr',fmt(ratio*100,0),'%']]);
    html+=`<div class="idcard"><span class="tag" style="background:${(over?cssVar('--bad'):cssVar('--ok'))}22;color:${over?cssVar('--bad'):cssVar('--ok')}">${over?'Flambement':'Stable'}</span><br><b>${over?'N dépasse Ncr':'N < Ncr'}</b><div class="desc">${over?'Le poteau flambe : instable.':'Approche Ncr pour le voir flamber.'}</div></div>`;
    html+=`<div><h4>Pas à pas</h4>${stepx('Charge critique','Ncr = π²·E·I/(k·L)²','Ncr = '+fmt(S.Ncr/1e3,0)+' kN')}${stepx('Élancement','λ = k·L/i','λ = '+fmt(S.lam,0))}</div>`;
    $("side").innerHTML=html;}
  rebuild();
 }
};

