/* ================= ÉTUDE — tashrih-style study page ================= */
let curAt=null,curP={};
function buildCarousel(){$("elemCarousel").innerHTML=Object.values(AT).map(a=>`<div class="e-card ${a.id===curAt.id?'sel':''}" data-el="${a.id}"><span class="ci">${(DATA[a.id]||{}).icon||'▪'}</span><span><span class="cn">${a.name}</span><br><span class="cf">${a.code}</span></span></div>`).join('');
  $("elemCarousel").querySelectorAll('.e-card').forEach(c=>c.onclick=()=>etudeOpen(c.dataset.el));}
function buildParams2(){$("paramBox2").innerHTML=curAt.params.map(p=>{
   if(p.type==='select')return `<label class="field"><span class="l">${p.label}</span><select data-p="${p.id}">${p.options.map(o=>`<option value="${o.v}" ${curP[p.id]==o.v?'selected':''}>${o.l}</option>`).join('')}</select></label>`;
   if(p.type==='number')return `<label class="field"><span class="l">${p.label}</span><input type="number" data-p="${p.id}" value="${curP[p.id]}" min="${p.min}" max="${p.max}" step="${p.step}"></label>`;
   return `<label class="field"><span class="l">${p.label} <b data-pv="${p.id}">${fmtParam(p,curP[p.id])}</b></span><input type="range" data-p="${p.id}" min="${p.min}" max="${p.max}" step="${p.step}" value="${curP[p.id]}"></label>`;}).join('');
  $("paramBox2").querySelectorAll('[data-p]').forEach(inp=>inp.addEventListener('input',()=>{const p=curAt.params.find(x=>x.id===inp.dataset.p);let v=inp.value;if(p.type!=='select')v=parseFloat(v);curP[p.id]=v;const pv=$("paramBox2").querySelector(`[data-pv="${p.id}"]`);if(pv)pv.textContent=fmtParam(p,v);runEtude();}));}
function fmtParam(p,v){return p.type==='select'?(p.options.find(o=>o.v==v)||{}).l||v:(fmt(v,p.dec==null?1:p.dec)+(p.unit?' '+p.unit:''));}
